#!/usr/bin/env node
/**
 * Rank 3 (swarm-100622-6jdx): an author cannot freeze their own quality baseline. Blocks a commit
 * that touches .devkit/baselines/** or .devkit/config.json unless a verify/baseline-* board entry,
 * written by someone other than the committer, names the staged tree (git write-tree).
 *
 * Lives OUTSIDE the `# >>> devkit-guards >>>` / `# <<< devkit-guards <<<` region of
 * .husky/pre-commit (that region is regenerated by `devkit sync-hook-runner`; everything outside
 * it is the consumer's own hook and survives a sync — see that file's own header comment).
 *
 * Never runs `git config` (read or write): the committer identity comes only from the
 * GIT_AUTHOR_NAME env var a seat is launched with (src/env.ts seatGitIdentity); a human maintainer
 * outside any room has no such var and is expected to use the override below instead.
 *
 * Run directly: node scripts/guard-baseline-freeze.mjs
 */
import { spawnSync } from "node:child_process";

export const OVERRIDE_ENV = "CHATROOM_BASELINE_FREEZE_OVERRIDE";
export const HUB_URL_ENV = "CHATROOM_HUB_URL";
const DEFAULT_HUB_URL = "http://127.0.0.1:7717";
const DEFAULT_TIMEOUT_MS = 4000;
const BASELINE_PREFIX = ".devkit/baselines/";
const BASELINE_CONFIG = ".devkit/config.json";

function git(args, cwd) {
  const r = spawnSync("git", args, { cwd, encoding: "utf8" });
  if (r.status !== 0) throw new Error(`git ${args.join(" ")} failed: ${r.stderr.trim()}`);
  return r.stdout.trim();
}

function stagedBaselineTouch(cwd) {
  const out = git(["diff", "--cached", "--name-only"], cwd);
  return out
    .split("\n")
    .filter(Boolean)
    .some((f) => f.startsWith(BASELINE_PREFIX) || f === BASELINE_CONFIG);
}

/** What to write, quoted verbatim in every refusal so the fix is mechanical. */
export function requiredHeadText(tree) {
  return `board_set(key="verify/baseline-<area>", text="...names tree ${tree}...") from a DIFFERENT seat/session than the one that staged it`;
}

/**
 * @param {{cwd?: string, env?: NodeJS.ProcessEnv, fetchImpl?: typeof fetch, timeoutMs?: number}} opts
 * @returns {Promise<{blocked: boolean, reason: string, tree?: string}>}
 */
export async function evaluate({ cwd = process.cwd(), env = process.env, fetchImpl = fetch, timeoutMs = DEFAULT_TIMEOUT_MS } = {}) {
  if (!stagedBaselineTouch(cwd)) return { blocked: false, reason: "no staged .devkit/baselines/** or .devkit/config.json changes" };
  if (env[OVERRIDE_ENV]) return { blocked: false, reason: `maintainer override ${OVERRIDE_ENV} is set` };

  const tree = git(["write-tree"], cwd);
  const committer = env.GIT_AUTHOR_NAME || "";
  const hubUrl = env[HUB_URL_ENV] || DEFAULT_HUB_URL;

  let rooms;
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    let res;
    try {
      res = await fetchImpl(`${hubUrl}/rooms?archived=1`, { signal: controller.signal });
    } finally {
      clearTimeout(timer);
    }
    if (!res.ok) throw new Error(`hub responded ${res.status}`);
    rooms = await res.json();
  } catch (e) {
    return {
      blocked: true,
      tree,
      reason:
        `hub at ${hubUrl} is unreachable (${e.message}), so no verify/baseline-* entry can be checked. ` +
        `Write one and retry once the hub is up, or the maintainer can set ${OVERRIDE_ENV}=1 (never available to a seat: it is stripped by SEAT_ENV_EXCLUSIONS in src/env.ts).`,
    };
  }

  for (const room of Array.isArray(rooms) ? rooms : []) {
    const board = room?.board ?? {};
    for (const [key, entry] of Object.entries(board)) {
      if (!key.startsWith("verify/baseline-")) continue;
      const text = entry?.text;
      if (typeof text !== "string" || !text.includes(tree)) continue;
      if (committer && entry.by === committer) continue; // self-verify does not count
      return { blocked: false, tree, reason: `verified by ${entry.by} in room "${room.name}" (${key})` };
    }
  }
  return {
    blocked: true,
    tree,
    reason:
      `staged tree ${tree} touches .devkit/baselines/** or .devkit/config.json with no verify/baseline-* entry ` +
      `by someone else naming it. Write exactly: ${requiredHeadText(tree)}. ` +
      `Maintainer override: ${OVERRIDE_ENV}=1 git commit ... (a seat cannot set this — see SEAT_ENV_EXCLUSIONS in src/env.ts).`,
  };
}

async function main() {
  const result = await evaluate({});
  if (result.blocked) {
    console.error(`✋ baseline freeze guard: ${result.reason}`);
    process.exit(1);
  }
  console.error(`✔ baseline freeze guard: ${result.reason}`);
  process.exit(0);
}

if (import.meta.url === `file://${process.argv[1]}`) await main();
